WITH matched_keys AS (SELECT id FROM transactions INTERSECT SELECT id FROM transactions WHERE HOUR(txn_time) BETWEEN 12 AND 16), reconciled AS (SELECT s.* FROM transactions s JOIN matched_keys k ON s.id = k.id) SELECT txn_type, DATE_TRUNC('QUARTER', txn_time) AS quarter_start, APPROX_PERCENTILE(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list, ROUND(AVG(amount), 2) AS avg_amount, COUNT(*) AS event_count, SUM(CASE WHEN txn_type = 'DEBIT' THEN amount ELSE 0 END) AS debit_amount FROM reconciled GROUP BY GROUPING SETS ((txn_type, DATE_TRUNC('QUARTER', txn_time)), (txn_type)) HAVING ROUND(AVG(amount), 2) >= 0 ORDER BY txn_type DESC
